#include <iostream>
#include <vector>
#include <string>
using namespace std;

class Fraction {
private:
    int num, den;
    static int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
    void reduce() {
        int g = gcd(num < 0 ? -num : num, den < 0 ? -den : den);
        if (g != 0) {
            num /= g;
            den /= g;
        }
        if (den < 0) {
            num = -num;
            den = -den;
        }
    }
public:
    Fraction(int n = 0, int d = 1) : num(n), den(d) {
        reduce();
    }
    Fraction operator+(const Fraction& o) const {
        return Fraction(num * o.den + o.num * den, den * o.den);
    }
    Fraction operator*(const Fraction& o) const {
        return Fraction(num * o.num, den * o.den);
    }
    friend ostream& operator<<(ostream& os, const Fraction& f);
};

ostream& operator<<(ostream& os, const Fraction& f) {
    if (f.den == 1) {
        return os << f.num;
    }
    return os << f.num << '/' << f.den;
}

class Polynomial {
    vector<Fraction> coef;
public:
    Polynomial(const vector<Fraction>& c) : coef(c) {}
    int degree() const {
        return (int)coef.size() - 1;
    }
    const Fraction& at(int i) const {
        return coef[i];
    }
    Fraction eval(const Fraction& x) const {
        Fraction result;
        for (int i = degree(); i >= 0; i--) {
            result = result * x + coef[i];
        }
        return result;
    }
};

ostream& operator<<(ostream& os, const Polynomial& p) {
    for (int i = p.degree(); i >= 0; i--) {
        os << "(" << p.at(i) << ")";
        if (i > 0) {
            os << "x^" << i << " + ";
        }
    }
    return os;
}

void printTable(ostream& out, const Polynomial& p, const vector<Fraction>& xs) {
    out << "P(x) = " << p << '\n';
    for (size_t i = 0; i < xs.size(); i++) {
        out << "P(" << xs[i] << ") = " << p.eval(xs[i]) << '\n';
    }
}

int main() {
    vector<Fraction> c = {Fraction(1, 2), Fraction(-3, 4), Fraction(2)};
    Polynomial p(c);
    vector<Fraction> xs = {Fraction(0), Fraction(1, 2), Fraction(-2), Fraction(4, 6)};
    printTable(cout, p, xs);
    cout << Fraction(6, -8) << " " << Fraction(0, 5) << endl;
    cout << Fraction(1, 2) + 1 << endl;
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
using namespace std;

class Shape {
protected:
    string name;
public:
    Shape(const string& n) : name(n) {}
    virtual ~Shape() {}
    virtual int area() const = 0;
    virtual void print(ostream& os) const {
        os << name << "(area=" << area() << ")";
    }
};

ostream& operator<<(ostream& os, const Shape& s) {
    s.print(os);
    return os;
}

class Square : public Shape {
    int side;
public:
    Square(const string& n, int s) : Shape(n), side(s) {}
    int area() const override {
        return side * side;
    }
};

class Rect : public Shape {
    int w, h;
public:
    Rect(const string& n, int width, int height) : Shape(n), w(width), h(height) {}
    int area() const override {
        return w * h;
    }
    void print(ostream& os) const override {
        Shape::print(os);
        os << " [" << w << "x" << h << "]";
    }
};

class Group : public Shape {
    vector<const Shape*> items;
public:
    Group(const string& n) : Shape(n) {}
    Group& add(const Shape& s) {
        items.push_back(&s);
        return *this;
    }
    int area() const override {
        int total = 0;
        for (size_t i = 0; i < items.size(); i++) {
            total += items[i]->area();
        }
        return total;
    }
    void print(ostream& os) const override {
        os << name << "{";
        for (size_t i = 0; i < items.size(); i++) {
            if (i > 0) {
                os << ", ";
            }
            os << *items[i];
        }
        os << "}";
    }
};

const Shape& largest(const vector<const Shape*>& v) {
    const Shape* best = v[0];
    for (size_t i = 1; i < v.size(); i++) {
        if (v[i]->area() > best->area()) {
            best = v[i];
        }
    }
    return *best;
}

void report(ostream& os, const vector<const Shape*>& v) {
    for (size_t i = 0; i < v.size(); i++) {
        os << i + 1 << ". " << *v[i] << '\n';
    }
    os << "largest: " << largest(v) << '\n';
}

int main() {
    Square a("sq", 3);
    Rect b("rect", 2, 5);
    Group inner("inner");
    inner.add(a).add(b);
    Group outer("outer");
    outer.add(inner).add(a);
    Group empty("empty");

    vector<const Shape*> all = {&a, &b, &inner, &outer, &empty};
    report(cout, all);

    const Shape& ref = b;
    cout << ref << endl;
    return 0;
}

