#include <iostream>
#include <iomanip>
#include <sstream>
#include <string>
using namespace std;

class Item {
    string name;
    int qty;
    double price;
public:
    Item() : name(""), qty(0), price(0.0) {}
    Item(const string& n, int q, double p) : name(n), qty(q), price(p) {}
    double total() const {
        return qty * price;
    }
    friend ostream& operator<<(ostream& os, const Item& it) {
        ostringstream tmp;
        tmp << it.name << " x" << it.qty;
        ios::fmtflags oldFlags = os.flags();
        streamsize oldPrecision = os.precision();
        os << setw(14) << left << tmp.str();
        os << right << fixed << setprecision(2) << setw(8) << it.total();
        os.flags(oldFlags);
        os.precision(oldPrecision);
        return os;
    }
};

class Inventory {
    Item items[4];
    int count;
public:
    Inventory() : count(0) {}
    bool add(const Item& it) {
        if (count >= 4) {
            return false;
        }
        items[count] = it;
        count++;
        return true;
    }
    double grand() const {
        double sum = 0;
        for (int i = 0; i < count; i++) {
            sum += items[i].total();
        }
        return sum;
    }
    friend ostream& operator<<(ostream& os, const Inventory& inv) {
        for (int i = 0; i < inv.count; i++) {
            os << inv.items[i] << '\n';
        }
        os << "TOTAL " << inv.grand() << '\n';
        return os;
    }
};

string toText(const Inventory& inv) {
    ostringstream ss;
    ss << inv;
    return ss.str();
}

int countLines(const string& s) {
    int n = 0;
    for (size_t i = 0; i < s.size(); i++) {
        if (s[i] == '\n') {
            n++;
        }
    }
    return n;
}

int main() {
    Inventory inv;
    Item pen("pen", 3, 1.25);
    inv.add(pen);
    inv.add(Item("notebook", 2, 4.5));
    inv.add(Item("ruler", 10, 0.75));
    inv.add(Item("eraser", 1, 0.5));
    bool ok = inv.add(Item("overflow", 1, 99.0));

    cout << inv;
    operator<<(cout, pen) << "|" << endl;

    string text = toText(inv);
    cout << countLines(text) << " lines, " << text.size() << " chars" << endl;
    cout << (ok ? "added" : "full") << " " << 1.0 / 3 << endl;
    return 0;
}

#include <iostream>
#include <sstream>
#include <string>
#include <cstdlib>
using namespace std;

struct Point {
    int x;
    int y;
};

ostream& operator<<(ostream& os, const Point& p) {
    return os << '(' << p.x << ", " << p.y << ')';
}

ostream& sep(ostream& os) {
    return os << " | ";
}

ostream& indent(ostream& os, int n) {
    for (int i = 0; i < n; i++) {
        os << "  ";
    }
    return os;
}

class Path {
    Point pts[8];
    int n;
public:
    Path() : n(0) {}
    Path& add(int x, int y) {
        if (n < 8) {
            pts[n].x = x;
            pts[n].y = y;
            n++;
        }
        return *this;
    }
    int size() const {
        return n;
    }
    Point& operator[](int i) {
        return pts[i];
    }
    const Point& operator[](int i) const {
        return pts[i];
    }
    int length() const {
        int total = 0;
        for (int i = 1; i < n; i++) {
            total += abs(pts[i].x - pts[i - 1].x) + abs(pts[i].y - pts[i - 1].y);
        }
        return total;
    }
    friend ostream& operator<<(ostream& os, const Path& p);
};

ostream& operator<<(ostream& os, const Path& p) {
    os << "<";
    for (int i = 0; i < p.n; i++) {
        os << p.pts[i];
        if (i + 1 < p.n) {
            os << " -> ";
        }
    }
    return os << "> len=" << p.length();
}

class Logger {
    ostream& out;
    int depth;
    int count;
public:
    Logger(ostream& o) : out(o), depth(0), count(0) {}
    void enter(const string& title) {
        indent(out, depth) << title << ":" << '\n';
        depth++;
    }
    void leave() {
        depth--;
    }
    Logger& line(const Path& p) {
        count++;
        indent(out, depth) << count << sep << p << '\n';
        return *this;
    }
    int total() const {
        return count;
    }
};

void shiftLast(Path& p, int dy) {
    Point& last = p[p.size() - 1];
    last.y += dy;
}

int main() {
    Path a;
    a.add(0, 0).add(3, 4).add(-1, 4);
    Path b;
    b.add(2, 2);
    Path empty;

    Logger log(cout);
    log.enter("paths");
    log.line(a).line(b);
    log.enter("after shift");
    shiftLast(a, -7);
    log.line(a).line(empty);
    log.leave();
    log.leave();
    log.enter("done");

    ostringstream buf;
    Logger quiet(buf);
    quiet.line(a);
    string captured = buf.str();
    cout << captured.size() << sep << quiet.total() << sep << log.total() << endl;
    cout << a[1] << sep << b[0] << endl;
    return 0;
}
